#!/usr/bin/env python3
"""
test_nota117.py — Prueba el llenado de comparativos para Nota 117 de E110 IND.

Uso:
  1. Coloca este archivo en cualquier carpeta.
  2. Ejecuta:  python test_nota117.py
  
  Por defecto corre en DRY-RUN (no escribe nada, solo muestra qué haría).
  Para escribir de verdad, cambia DRY_RUN = False al final del archivo.

Requisitos:
  pip install httpx mcp pydantic python-dotenv openpyxl
"""

import asyncio, base64, importlib, importlib.util, os, pathlib, sys, tempfile, json

# ── Credenciales ───────────────────────────────────────────────────────────────
CLIENT_ID     = "db2c551e-e18a-417e-8e52-d182716b8ef2"
CLIENT_SECRET = "wk_secret:oa2c:DzlUCmBQDv6raPxG09me"
WORKSPACE_ID  = "w_34913aadaa38420eabd7e4d341b78a1a"

# ── Configuración de la prueba ─────────────────────────────────────────────────
SOCIEDAD      = "E110"
TIPO          = "IND"
HOJA_FILTRO   = ["117"]          # Solo la nota 117
DRY_RUN       = True             # Cambiar a False para escribir de verdad

# ── MCP v2 embebido ────────────────────────────────────────────────────────────
_MCP_V2_B64 = ""

def _load_mcp_v2(tmpdir: pathlib.Path):
    src = base64.b64decode(_MCP_V2_B64.encode()).decode("utf-8")
    mcp_file = tmpdir / "workiva_mcp_v2.py"
    mcp_file.write_text(src, encoding="utf-8")
    (tmpdir / ".env").write_text(
        f"WORKIVA_CLIENT_ID={CLIENT_ID}\n"
        f"WORKIVA_CLIENT_SECRET={CLIENT_SECRET}\n"
        f"WORKIVA_WORKSPACE_ID={WORKSPACE_ID}\n",
        encoding="utf-8",
    )
    spec = importlib.util.spec_from_file_location("workiva_mcp_v2", mcp_file)
    mod  = importlib.util.module_from_spec(spec)
    mod.__file__ = str(mcp_file)
    sys.modules["workiva_mcp_v2"] = mod
    spec.loader.exec_module(mod)
    return mod

async def main():
    tmpdir = pathlib.Path(tempfile.mkdtemp(prefix="test_nota117_"))
    print(f"Temp dir: {tmpdir}")

    mcp = _load_mcp_v2(tmpdir)
    mcp._wk._client = None  # reset httpx client

    # 1. Buscar el archivo de E110 IND (excluir prefijos CHN y LC — son fuentes, no targets)
    print("\nBuscando archivos en Workiva...")
    files = await mcp._load_all_files()

    def _es_target(name: str) -> bool:
        nl = name.strip().lower()
        if nl.startswith("(chn)") or nl.startswith("(lc)"):
            return False
        return SOCIEDAD.lower() in nl and TIPO.lower() in nl and "base" in nl

    matches = {k: v for k, v in files.items() if _es_target(k)}
    if not matches:
        # Intentar sin filtro BASE
        matches = {k: v for k, v in files.items()
                   if not k.strip().lower().startswith(("(chn)", "(lc)"))
                   and SOCIEDAD in k and TIPO in k}

    print(f"\nArchivos target {SOCIEDAD} {TIPO} (sin prefijo CHN/LC):")
    for name in sorted(matches):
        print(f"  {name}")

    if not matches:
        print("\nERROR: No se encontró archivo target. Todos los archivos con E110 IND:")
        for name in sorted(k for k in files if SOCIEDAD in k and TIPO in k):
            print(f"  {name}")
        return

    # Ordenar por fecha real (mm-yyyy o yyyy) extraída del nombre
    def _fecha_key(name: str):
        import re
        m = re.search(r'(\d{2})-(\d{4})', name)
        if m:
            return (int(m.group(2)), int(m.group(1)))
        m2 = re.search(r'(\d{4})', name)
        return (int(m2.group(1)), 0) if m2 else (0, 0)

    ss_name, ss_id = max(matches.items(), key=lambda x: _fecha_key(x[0]))
    print(f"\nUsando (más reciente por fecha): {ss_name}")
    print(f"ID: {ss_id}")

    # Listar TODAS las hojas del archivo target
    print("\nHojas en el archivo target (las que contienen '117' marcadas):")
    tgt_sheets_dict = await mcp._get_sheets(ss_id)
    sheet117 = None
    for sname in sorted(tgt_sheets_dict):
        marker = " <-- MATCH '117'" if "117" in sname.lower() else ""
        print(f"  {repr(sname)}{marker}")
        if "117" in sname.lower():
            sheet117 = sname

    # Verificar si la hoja 117 está en los archivos fuente
    if sheet117:
        print(f"\nVerificando '{sheet117}' en fuentes:")
        src_bal_sheets = await mcp._get_sheets(
            next((v for k, v in files.items() if "12-2025" in k and SOCIEDAD in k and TIPO in k), None) or ""
        ) if any("12-2025" in k and SOCIEDAD in k and TIPO in k for k in files) else {}
        print(f"  En balance (12-2025): {'SI' if sheet117 in src_bal_sheets else 'NO'}")
    else:
        print("\nNinguna hoja contiene '117' en su nombre en el archivo seleccionado.")

    # DEBUG: imprimir valores exactos de las primeras 10 filas para la hoja 117
    if sheet117:
        print(f"\nDEBUG — valores exactos primeras 10 filas de '{sheet117}':")
        sid117 = tgt_sheets_dict[sheet117]
        cells117 = await mcp._read_sheet_cells(ss_id, sid117)
        for i, row in enumerate(cells117[:10]):
            row_vals = []
            for j, cell in enumerate(row[:30]):  # primeras 30 columnas
                if isinstance(cell, dict):
                    v = cell.get("calculatedValue") or cell.get("value") or ""
                    if str(v).strip():
                        row_vals.append(f"[{j}]={repr(str(v).strip())}")
            if row_vals:
                print(f"  fila {i}: {', '.join(row_vals)}")

    # 2. Llamar fill_comparatives con include_sheets=[117]
    params = mcp.FillComparativesInput(
        spreadsheet_id=ss_id,
        dry_run=DRY_RUN,
        include_sheets=HOJA_FILTRO,
        max_sheets=10,
        apply_default_excludes=False,
    )

    mode = "DRY-RUN (no escribe)" if DRY_RUN else "*** ESCRITURA REAL ***"
    print(f"\nEjecutando fill_comparatives en modo: {mode}")
    print(f"Filtro de hojas: {HOJA_FILTRO}")
    print("-" * 60)

    result_json = await mcp.workiva_fill_comparatives(params)
    result = json.loads(result_json)

    print(json.dumps(result, indent=2, ensure_ascii=False))

    # Resumen
    print("\n" + "=" * 60)
    print("RESUMEN")
    print(f"  Hojas candidatas: {result.get('total_candidate_sheets', 0)}")
    print(f"  Lote procesado:   {result.get('batch_size', 0)}")
    print(f"  Cols escritas:    {result.get('total_cols_written', 0)}")
    for sh in result.get("sheets_processed", []):
        print(f"  Hoja {sh['sheet']}: cols={sh.get('comp_cols', [])}, escritas={sh.get('cols_written', 0)}")
    for sk in result.get("sheets_skipped", [])[:10]:
        print(f"  Omitida: {sk}")

asyncio.run(main())
